# Load grids from session
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
sessions_file = os.path.join(d, '../../sessions/' + os.path.basename(d) + '.jsonl')

def load_grids():
    G = {}
    try:
        t = open(sessions_file).read()
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
            k, h, w = m[1], int(m[2]), int(m[3])
            # Get remaining text until next section
            rest = t[m.end():]
            lines = []
            in_grid = False
            for line in rest.split('\n'):
                if not in_grid:
                    if line.strip().startswith('Demo pair') or line.strip().startswith('Test input'):
                        continue
                    elif ':' in line and any(x.isdigit() for x in line.split(':')[-1].strip()):
                        lines.append(line.strip())
                        in_grid = True
                elif in_grid:
                    if 'Wrong attempts' in line or 'Reply with' in line:
                        break
                    if line.strip() == '' and len(lines) > 0:
                        break
                    lines.append(line.strip())

            if lines:
                grid = [[int(x) for x in row.split()] for row in lines[:h]]
                G[k] = grid
    except Exception as e:
        print(f"Error loading grids: {e}")
        return {}
    return G

G = load_grids()
print("Loaded grids:", sorted(G.keys()))

if G:
    for name, grid in sorted(G.items()):
        print(f"\n{name} ({len(grid)}x{len(grid[0])}):")
        print(json.dumps(grid))

